import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十五卦 豐 雷火 豐震上離下","description":"周易 - 第五十五卦 豐 雷火 豐震上離下","frontmatter":{"title":"第五十五卦 豐 雷火 豐震上離下","description":"周易 - 第五十五卦 豐 雷火 豐震上離下"},"headers":[],"relativePath":"classics/zhouyi/056.md","filePath":"classics/zhouyi/056.md"}'),l={name:"classics/zhouyi/056.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="豐" tabindex="-1">豐 <a class="header-anchor" href="#豐" aria-label="Permalink to “豐”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，王假之，勿憂，宜日中。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>豐，大也。明以動，故豐。王假之，尚大也。勿憂宜日中，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況人於人乎？況於鬼神乎？</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雷電皆至，豐；君子以折獄致刑。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>遇其配主，雖旬無咎，往有尚。象曰：雖旬無咎，過旬災也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>豐其蔀，日中見鬥，往得疑疾，有孚發若，吉。象曰：有孚發若，信以發志也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>豐其沛，日中見昧，折其右肱，無咎。象曰：豐其沛，不可大事也。折其右肱，終不可用也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>豐其蔀，日中見鬥，遇其夷主，吉。象曰：豐其蔀，位不當也。日中見鬥，幽不明也。遇其夷主，吉；行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>來章，有慶譽，吉。象曰：六五之吉，有慶也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>豐其屋，蔀其家，窺其戶，闃其無人，三歲不見，兇。象曰：豐其屋，天際翔也。窺其戶，闃其無人，自藏也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
